/* ================================================================
 * Special byte: space (0x20) → 0xC4 0xA0
 * ================================================================ */

MU_TEST(test_decode_space) {
    u8 raw[] = {0xC4, 0xA0}; /* encoded space */
    char out[64] = {0};
    int n = decode(raw, 2, out, sizeof(out));
    mu_assert_int_eq(1, n);
    mu_assert_int_eq(' ', out[0]);
}

/* ================================================================
 * Chinese text roundtrip (UTF-8 → GPT2-encode → decode → UTF-8)
 * "你好" = E4 BD A0 E5 A5 BD
 * E4→C3 A4  BD→C2 BD  A0→C5 82  E5→C3 A5  A5→C2 A5  BD→C2 BD
 * ================================================================ */

MU_TEST(test_decode_chinese) {
    /* GPT-2 encoded bytes for "你好" (standard mapping) */
    u8 raw[] = {0xC3, 0xA4, 0xC2, 0xBD, 0xC5, 0x82,
                0xC3, 0xA5, 0xC2, 0xA5, 0xC2, 0xBD};
    char out[64] = {0};
    int n = decode(raw, 12, out, sizeof(out));
    mu_assert_int_eq(6, n);
    /* Verify raw UTF-8 bytes for "你好" */
    u8 expected[] = {0xE4, 0xBD, 0xA0, 0xE5, 0xA5, 0xBD};
    mu_assert_int_eq(6, n);
    for (int i = 0; i < 6; i++)
        mu_assert_int_eq(expected[i], (u8)out[i]);
}

/* ================================================================
 * Mixed content: printable ASCII + encoded non-printable + C2/C3/C4/C5
 * ================================================================ */

MU_TEST(test_decode_mixed) {
    /* "Hi" + space(encoded) + "!" + byte 0x80(encoded) + byte 0xFF(encoded) */
    u8 raw[] = {
        'H', 'i',                   /* 0x48, 0x69 → direct */
        0xC4, 0xA0,                 /* space → 0x20 */
        '!',                        /* 0x21 → direct */
        0xC4, 0xA2,                 /* → 0x80 (byte 0x80 maps to C4 A2) */
        0xC3, 0xBF,                 /* → 0xFF */
    };
    char out[64] = {0};
    int n = decode(raw, 9, out, sizeof(out));
    mu_assert_int_eq(6, n);
    mu_assert_int_eq('H',  out[0]);
    mu_assert_int_eq('i',  out[1]);
    mu_assert_int_eq(' ',  out[2]);
    mu_assert_int_eq('!',  out[3]);
    mu_assert_int_eq(0x80, (u8)out[4]);
    mu_assert_int_eq(0xFF, (u8)out[5]);
}

/* ================================================================
 * Japanese: "こんにちは" (konnichiwa)
 * UTF-8: E3 81 93 | E3 82 93 | E3 81 AB | E3 81 A1 | E3 81 AF
 * Per-byte standard mapping:
 *   E3→C3 A3, 81→C4 A3, 93→C4 B5 | 82→C4 A4 | AB→C2 AB | A1→C2 A1 | AF→C2 AF
 * ================================================================ */

MU_TEST(test_decode_japanese) {
    u8 encoded[] = {
        0xC3, 0xA3, 0xC4, 0xA3, 0xC4, 0xB5,  /* こ */
        0xC3, 0xA3, 0xC4, 0xA4, 0xC4, 0xB5,  /* ん */
        0xC3, 0xA3, 0xC4, 0xA3, 0xC2, 0xAB,  /* に */
        0xC3, 0xA3, 0xC4, 0xA3, 0xC2, 0xA1,  /* ち */
        0xC3, 0xA3, 0xC4, 0xA3, 0xC2, 0xAF,  /* は */
    };
    u8 expected[] = {0xE3, 0x81, 0x93, 0xE3, 0x82, 0x93,
                     0xE3, 0x81, 0xAB, 0xE3, 0x81, 0xA1,
                     0xE3, 0x81, 0xAF};
    char out[64] = {0};
    int n = decode(encoded, sizeof(encoded), out, sizeof(out));
    mu_assert_int_eq(15, n);
    for (int i = 0; i < 15; i++)
        mu_assert_int_eq(expected[i], (u8)out[i]);

    /* Also verify roundtrip via helper. */
    u8 enc[64]; char dec[64];
    mu_assert_int_eq(15, roundtrip_check("こんにちは", enc, sizeof(enc), dec, sizeof(dec)));
}

/* ================================================================
 * Japanese mixed with ASCII: "Hello World! こんにちは"
 * ================================================================ */

MU_TEST(test_decode_japanese_mixed_ascii) {
    const char *text = "Hello World! ";
    const char *jp   = "こんにちは";
    u8 enc[256]; char dec[256];
    char full[256];
    snprintf(full, sizeof(full), "%s%s", text, jp);
    int raw_len = (int)strlen(full);
    mu_assert_int_eq(raw_len, roundtrip_check(full, enc, sizeof(enc), dec, sizeof(dec)));
}

/* ================================================================
 * Korean: "안녕하세요" (annyeonghaseyo)
 * UTF-8: EC 95 88 | EB 85 95 | ED 95 98 | EC 84 B8 | EC 9A 94
 * Per-byte standard mapping:
 *   EC→C3 AC, 95→C4 B7, 88→C4 AA | EB→C3 AB, 85→C4 A7
 *   ED→C3 AD, 98→C4 BA | 84→C4 A6, B8→C2 B8 | 9A→C4 BC, 94→C4 B6
 * ================================================================ */

MU_TEST(test_decode_korean) {
    u8 encoded[] = {
        0xC3, 0xAC, 0xC4, 0xB7, 0xC4, 0xAA,  /* 안 */
        0xC3, 0xAB, 0xC4, 0xA7, 0xC4, 0xB7,  /* 녕 */
        0xC3, 0xAD, 0xC4, 0xB7, 0xC4, 0xBA,  /* 하 */
        0xC3, 0xAC, 0xC4, 0xA6, 0xC2, 0xB8,  /* 세 */
        0xC3, 0xAC, 0xC4, 0xBC, 0xC4, 0xB6,  /* 요 */
    };
    u8 expected[] = {0xEC, 0x95, 0x88, 0xEB, 0x85, 0x95,
                     0xED, 0x95, 0x98, 0xEC, 0x84, 0xB8,
                     0xEC, 0x9A, 0x94};
    char out[64] = {0};
    int n = decode(encoded, sizeof(encoded), out, sizeof(out));
    mu_assert_int_eq(15, n);
    for (int i = 0; i < 15; i++)
        mu_assert_int_eq(expected[i], (u8)out[i]);

    /* Roundtrip via helper. */
    u8 enc[64]; char dec[64];
    mu_assert_int_eq(15, roundtrip_check("안녕하세요", enc, sizeof(enc), dec, sizeof(dec)));
}

/* ================================================================
 * Korean mixed with ASCII: "안녕! Hello?"
 * ================================================================ */

MU_TEST(test_decode_korean_mixed_ascii) {
    u8 enc[256]; char dec[256];
    /* "안녕! Hello?" = 3 + 3 + 1 + 1 + 5 + 1 = 14 bytes */
    mu_assert_int_eq(14, roundtrip_check("안녕! Hello?", enc, sizeof(enc), dec, sizeof(dec)));
}

/* ================================================================
 * Emoji: "😀🎉"
 * 😀 U+1F600 → UTF-8: F0 9F 98 80
 * 🎉 U+1F389 → UTF-8: F0 9F 8E 89
 *
 * Per-byte standard mapping:
 *   F0→C3 B0, 9F→C5 81, 98→C4 BA, 80→C4 A2  →  😀
 *   F0→C3 B0, 9F→C5 81, 8E→C4 B0, 89→C4 AB  →  🎉
 * ================================================================ */

MU_TEST(test_decode_emoji) {
    u8 encoded[] = {
        0xC3, 0xB0, 0xC5, 0x81, 0xC4, 0xBA, 0xC4, 0xA2,  /* 😀 */
        0xC3, 0xB0, 0xC5, 0x81, 0xC4, 0xB0, 0xC4, 0xAB,  /* 🎉 */
    };
    u8 expected[] = {0xF0, 0x9F, 0x98, 0x80, 0xF0, 0x9F, 0x8E, 0x89};
    char out[32] = {0};
    int n = decode(encoded, sizeof(encoded), out, sizeof(out));
    mu_assert_int_eq(8, n);
    for (int i = 0; i < 8; i++)
        mu_assert_int_eq(expected[i], (u8)out[i]);

    /* Roundtrip via helper. */
    u8 enc[64]; char dec[64];
    mu_assert_int_eq(8, roundtrip_check("😀🎉", enc, sizeof(enc), dec, sizeof(dec)));
}

/* ================================================================
 * Emoji + CJK mix: "Hello 😀 你好 こんにちは 안녕"
 * Stress test combining ASCII + emoji + Chinese + Japanese + Korean.
 * ================================================================ */

MU_TEST(test_decode_unicode_mixed) {
    const char *text = "Hello 😀 你好 こんにちは 안녕";
    int raw_len = (int)strlen(text);
    u8 enc[512]; char dec[512];
    mu_assert_int_eq(raw_len, roundtrip_check(text, enc, sizeof(enc), dec, sizeof(dec)));
}

